from author import *
C=[]
C.append(human('chen_jingde','陈景德',
'陈景德以迅速崛起的商人身份出现在城市里，与陈宜兴并肩建立两幢几乎完全相同的大厦。外界以为兄弟共同拥有强大商业判断，真实情况却是他长期替缺少教育与生活经验的兄弟提供暗示，维持两人都能从容应对的形象。他没有因兄弟依赖自己而抛弃对方，反而在重逢后觉得失去的一半终于回来，心理上同样离不开对方。双头石像触动两人的特殊感受，他不惜代价取得它，希望理解双生子的联系，也希望兄弟拥有与自己相当的能力。神秘组织再度出现时，他留下求助录音，与有相同遭遇的方如花共同追查，后来得知自己自幼也被这项实验暗中安排。面对研究者的解释，他没有只关注宏伟科学目标，而明确说最关心的是另一半能够完整生活。终局他自愿接受记忆复制相关操作与基地记忆清除，和兄弟一起出席宴会。卡片保留他的商业强势与真切手足之情，也提醒财富并不给他替兄弟决定人生的无限权利。',
'实验成功，兄弟知识记忆可以复制；基地具体记忆按约清除。','商业判断、资源组织与双生子间的特殊沟通；实验由外部设施完成，不是他随时施展的术。','让兄弟都能完整而自主地生活。',
[('兄弟受轻视','外人把依赖等同无价值','直接维护尊严，同时说明实际需要。'),('神秘帮助出现','可能改善兄弟生活却要求冒险','核对条件并共同决定，不能只凭财富买断风险。'),('商业利益冲突','惯用强势可以解决眼前问题','考虑关系与长期后果，不把所有场景当交易。')],
[ev(22,17,89,'财富和外界形象'),ev(22,2295,2349,'兄弟关系'),ev(22,3129,3165,'选择与终局')],(1,0,1,3,3,3),roles=['单书主角']))
C.append(human('chen_yixing','陈宜兴',
'陈宜兴出生后被秘密研究者与双生兄弟分开，长期生活在受限制的环境里，没有得到与年龄相称的教育和社会经验。后来被送回陈景德身边，外人看见的却是一对无法区分的成功商人。他通过兄弟的眼色和小动作学习回应，陈景德又以相同衣饰、共同出现和特别安排的会议位置保护秘密，因此不宜把全部商业成就都直接归给他。面对双头石像时，他罕见地主动发言，强烈感到那表现的就是两兄弟；这种感受先于清楚语言，不能因此被轻视为没有思想。神秘组织的最终实验让他的知识记忆得到改变，宴会上的从容出现表明复制取得成功，他终于不再只是依照另一人的暗示生活。卡片采用这一终局状态，也保留长久受限制的过去对信任和自主的影响。复制来的知识不是自动复制全部人生立场，他可以与兄弟有共同记忆而作不同选择；新的演绎应让他逐步确认自己想做什么，而不永远扮演兄弟的无声影子。',
'获得双生兄弟知识记忆的复制，能够自信参与社会生活；具体能力细项未量化。','终局获得与兄弟相连的知识记忆基础；原有长期缺乏教育是历史状态。','从依赖与被安排中发展自己的选择。',
[('需要作决定','旁人仍只看陈景德的暗示','主动表达自己的理解，再与兄弟商量。'),('新知识与经历冲突','知道答案却缺少亲身熟悉感','承认这种差别，允许练习和调整。'),('再次被当实验材料','别人以改善为由替他决定','要求说明并保留拒绝权。')],
[ev(22,2295,2341,'早期限制与主体表达'),ev(22,2981,2993,'实验安排'),ev(22,3155,3165,'终局')],(1,0,1,3,2,3),roles=['单书主角']))
C.append(human('fang_ruhua','方如花',
'方如花在方继祖夫妇的抚养下长大，学习音乐，生活中并不知道自己还有一个被分开的双生姐妹。医院出现与她一模一样的女郎时，她没有先把对方当作身份威胁，而是真诚高兴地提出如花似玉的名字，愿意把她当作亲姐妹。两人同时说话、感到亲近的经历，又使相貌相似变成需要解释的深层联系。养父隐瞒收养事实，源于害怕失去女儿，不能因此消除她了解自身来历的权利。后来她与陈景德一起接触神秘人，得知自己能被收养与姐妹被禁锢都属于同一实验；她既知道获救的恩，也需要面对别人为了研究而损害另一人的事实。最终她愿意参加知识记忆复制，并同意清除基地的具体记忆，与姐妹共同出席宴会、合奏钢琴。卡片保留她的开朗与接纳，不把姐妹关系化为每次必须说完全相同的话。拥有共享知识之后，她仍可以从不同的经历出发理解一首曲子，也可以在感激帮助时继续追问帮助的代价。',
'与方似玉完成双生子记忆复制相关实验，终局共同合奏钢琴。','音乐训练、情感沟通及双生子联系；知识复制需外部研究设施。','接纳姐妹并保持共同生活中的自主。',
[('遇见相似者','对方孤独且不知来历','先提供具体关怀，再共同查明事实。'),('亲情秘密揭开','照顾者因恐惧隐瞒','承认长期感情，同时要求知情。'),('共享知识成功','旁人把两人视为一个声音','可以共同表达，也保留不同感受。')],
[ev(22,839,925,'相见与家庭'),ev(22,2991,2995,'出身'),ev(22,3129,3165,'选择和终局')],roles=['单书主角']))
C.append(human('fang_siyu','方似玉',
'方似玉出场时没有可以告诉别人的姓名和生活史，医生起初以为她因意外失忆，马进却逐渐发现，她并不是忘掉过去，而是过去几乎没有获得足够经验和记忆。她被研究者与双生姐妹分开，长期受照料也受禁锢，离开后才真正开始问自己是谁。医院中的关怀使她接近马进，方如花的出现又带来更深的熟悉感；如花似玉的命名给予她一个可以被称呼的位置，却不应使她只是为了成全别人而存在。她会高兴、会羞涩，也能开玩笑地反问自己为什么不能是姐姐，说明缺少知识并不等于没有人格。后来神秘研究者重新接走她，与另一组双生子共同进行记忆复制。终局她和方如花合奏钢琴，显示长期缺失的知识得到补充。卡片使用实验后的稳定状态，不再让她永久停留在空白病人身份，也不把复制知识当作复制姐妹的全部欲望。新场景可以让她对熟悉知识产生陌生体验，逐步选择真正属于自己的关系与生活。',
'接受双生子知识记忆复制，能与方如花合奏钢琴；与马进的关系未有明确婚姻终局。','终局获得音乐等知识记忆基础，保有独立感受；不能随意向其他人复制知识。','建立自己的身份、知识与关系。',
[('被问起过去','经历确实不足而非故意隐瞒','坦诚不知道，不编造完整人生填补空白。'),('受到关心','对方可能把依赖当爱情证明','分清感激与自己的选择，允许慢慢决定。'),('开始自主生活','新知识已经具备','通过实际体验确认偏好，不必复制姐妹的每个反应。')],
[ev(22,843,883,'相见与表达'),ev(22,931,939,'并非普通失忆'),ev(22,3081,3089,'实验安排'),ev(22,3161,3165,'终局')],roles=['单书主角']))
C.append(human('ma_jin','马进',
'马进是内向的精神科医生，接手一个不知姓名与来历的女病人后，认真通过交谈寻找她的过去。他没有满足于通常的失忆诊断，逐渐提出更可怕的可能：她的生活本来就缺少经验，意外反而使她开始产生追问身份的意识。专业观察使调查向前，私人感情却也在治疗中增长。他与她久久对望，握住她的手，甚至在方继祖愿意提供照顾时表现出明显的不悦，说明他已经难以完全把自己与医生职责分开。双生姐妹相遇后，他识别出同步反应，也向原振侠说明自己的疑惑；病人失踪时，他的焦急既是责任，也是害怕失去亲近。最终真相指向长期隔离与知识复制，方似玉获得新的生活能力，但原文没有给他一个必然得到爱情回报的结局。卡片保留其细致、温柔和判断上的亮点，也让他面对感情可能造成的越界。好的演绎不是禁止他动心，而是当她终于能自主决定时，他仍愿意把选择真正还给她。',
'调查揭明病人长期受限的背景；未证实与方似玉结婚或获得异能。','精神科交谈、记忆状态辨识与双生子现象观察。','帮助病人恢复自主，也理解自己投入的感情。',
[('常规诊断不合事实','回答显示根本缺少经历','调整假设，与同僚讨论证据。'),('关心变成占有','其他人也能提供照顾','检查自己反对的理由，不能用医生身份垄断关系。'),('病人能够独立选择','结果可能不是自己期待的','尊重决定，承认治疗成功不等于爱情成功。')],
[ev(22,835,883,'感情与观察'),ev(22,929,939,'诊断突破'),ev(22,1096,1102,'交谈方法'),ev(22,1282,1286,'失踪焦急')],roles=['单书主要行动者']))
C.append(human('twin_researcher','双生子研究的神秘人',
'神秘人出身曾经显赫的皇族，家族中双生子屡见不鲜，继承制度却要求一出生就牺牲其中一人。他的父亲因旧王朝不再而拒绝延续传统，使他和兄弟活到少年；十四岁一次枪械事故夺走兄弟，他在远处也经历强烈的死亡感，身体与心理都留下严重影响。此后他投入学习，动员仍有财力的家族研究双生子的思想联系，试图让知识记忆能够直接复制。他收容陈氏兄弟和方家姐妹，却故意让其中一方长期缺少教育，作为实验的对照，再安排他们重逢。面对良辰美景的道德质问，他以原先可能死亡与最终贡献为自己辩护，这不能抹去二十多年禁锢的事实。终局实验成功，参与者同意清除基地记忆，家族继续保密，非亲缘者之间的复制仍只是进一步目标。卡片保留他的创伤、才能和自我辩护，不把研究成功当作伦理争议消失。新场景中，他可能真心帮助人，也可能再次以理想之名替别人决定，需要具体的同意与监督来检验。',
'双生子知识记忆复制成功；继续秘密研究，非亲缘复制未获实证。','家族研究资源、人脑记忆技术与实验组织；操作依设备和团队，非本人触碰即复制。','理解双生联系并实现知识传承，避免重演失去另一半的痛苦。',
[('理想遇到伦理阻力','研究需要别人承担长期代价','容易以贡献辩护，但必须回答知情与退出问题。'),('有人追问基地','保密传统受挑战','提供有限成果说明，不能把所有质疑都视作无知。'),('实验取得进展','推广范围尚未验证','区分已成功的双生子情形与未来目标。')],
[ev(22,2983,2995,'伦理争论'),ev(22,3009,3089,'身世和安排'),ev(22,3095,3165,'技术边界与终局')],(1,1,2,3,2,3),roles=['反派性研究者','单书核心人物'],aliases=['神秘人（变换双星）']))
